update coop_settlement
set status = 1, payout_time = #{payoutTime}
where id = #{id} and del_flag = 0 and status = 0

mapper.select:
select  from coop_settlement
where del_flag = 0 and merchant_id = #{merchantId}
order by create_time desc

select  from coop_settlement
where del_flag = 0 and beneficiary_role = #{role} and beneficiary_id = #{beneficiaryId}
order by create_time desc


